-- 0001_init: the six tables that carry the product.
--
-- Conventions (CLAUDE.md):
--   * UUID v4 primary keys, generated by gen_random_uuid() (built into PG 13+,
--     no pgcrypto extension needed).
--   * All instants are timestamptz and stored UTC. Display conversion to
--     Asia/Almaty happens in the client, never here.
--   * A call time is a wall-clock time on a date, not an instant: shooting_day
--     stores shoot_date (date) + call_time (time), never a single timestamp.

BEGIN;

CREATE TABLE project (
    id         uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    name       text        NOT NULL CHECK (length(btrim(name)) > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- The central entity. Everything the impact view walks starts from a day.
CREATE TABLE shooting_day (
    id         uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid        NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    shoot_date date        NOT NULL,
    call_time  time        NOT NULL,
    location   text        NOT NULL DEFAULT '',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Days are listed per project in date order; no unique constraint on
-- (project_id, shoot_date) because a production can run two units in one day.
CREATE INDEX shooting_day_project_date_idx ON shooting_day (project_id, shoot_date);

CREATE TABLE scene (
    id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id      uuid        NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    -- Nullable on purpose: unscheduled scenes exist. Unscheduling a day's scene
    -- must not delete it, hence SET NULL.
    shooting_day_id uuid        REFERENCES shooting_day (id) ON DELETE SET NULL,
    -- text, not int: real scene numbers look like "12A" or "7pt2".
    number          text        NOT NULL CHECK (length(btrim(number)) > 0),
    description     text        NOT NULL DEFAULT '',
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, number)
);

CREATE INDEX scene_shooting_day_idx ON scene (shooting_day_id);

CREATE TABLE participant (
    id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id   uuid        NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    display_name text        NOT NULL CHECK (length(btrim(display_name)) > 0),
    email        text,
    role         text        NOT NULL CHECK (role IN ('producer', 'crew', 'cast')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

-- One person per project, case-insensitively, when an email is known.
CREATE UNIQUE INDEX participant_project_email_idx
    ON participant (project_id, lower(email))
    WHERE email IS NOT NULL;

CREATE INDEX participant_project_idx ON participant (project_id);

-- The join table that makes the impact view possible: who is needed in a scene.
CREATE TABLE scene_participant (
    scene_id       uuid        NOT NULL REFERENCES scene (id) ON DELETE CASCADE,
    participant_id uuid        NOT NULL REFERENCES participant (id) ON DELETE CASCADE,
    created_at     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (scene_id, participant_id)
);

-- Needed for the other direction: "which scenes is this person in".
CREATE INDEX scene_participant_participant_idx ON scene_participant (participant_id);

-- Append-only audit log. Never UPDATEd, never DELETEd — a change_event row is
-- the record that something happened, so correcting one means writing a new one.
CREATE TABLE change_event (
    id                   uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id           uuid        NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    -- Null when the actor is the system rather than a person, and kept as NULL
    -- if the participant is later removed: the log outlives its subjects.
    actor_participant_id uuid        REFERENCES participant (id) ON DELETE SET NULL,
    entity_type          text        NOT NULL CHECK (entity_type IN ('shooting_day', 'scene', 'participant', 'scene_participant')),
    entity_id            uuid        NOT NULL,
    -- Field diffs as {"field": {"from": ..., "to": ...}}. jsonb, not a table:
    -- the log is read whole and never queried by individual field.
    diff                 jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at           timestamptz NOT NULL DEFAULT now()
);

-- Cursor pagination over the feed is (created_at, id) descending.
CREATE INDEX change_event_project_created_idx
    ON change_event (project_id, created_at DESC, id DESC);

COMMIT;
